namespace Razy\Database\Schema;

use Razy\Database\Column;
use Razy\Database\Table;
use Razy\Database\Table\TableHelper;
use Razy\Exception\DatabaseException;

/**
 * RZ-07: renders the Table / Column / TableHelper DSL as Postgres DDL.
 *
 * Mapping (MySQL DSL → Postgres): auto → INTEGER/BIGINT GENERATED BY DEFAULT
 * AS IDENTITY; TINYINT(1)/bool → BOOLEAN; other TINYINT, YEAR → SMALLINT;
 * MEDIUMINT/INT → INTEGER; *TEXT → TEXT; DECIMAL → NUMERIC(p,s); FLOAT → REAL;
 * DOUBLE → DOUBLE PRECISION; DATETIME/TIMESTAMP → TIMESTAMP(0); JSON → JSONB;
 * *BLOB/*BINARY → BYTEA. Index keys become CREATE INDEX statements (FULLTEXT →
 * GIN over to_tsvector('simple', …)); column UNIQUE keys are unique
 * indexes "<table>_<col>_key" so dropIndex('<col>') removes them as on
 * MySQL; PRIMARY stays a table constraint; comments become COMMENT ON. Charset, collation, engine,
 * zerofill and FIRST/AFTER have no Postgres meaning and are ignored.
 * ON UPDATE CURRENT_TIMESTAMP, SPATIAL, ENUM and SET are refused (a
 * DatabaseException) rather than approximated.
 */
final class PostgresGrammar
{
    /** Postgres truncates identifiers to 63 bytes (NAMEDATALEN - 1). */
    private const MAX_IDENTIFIER = 63;

    public static function quote(string $identifier): string
    {
        return '"' . \str_replace('"', '""', \trim($identifier, '`')) . '"';
    }

    public static function literal(string $value): string
    {
        if (\str_contains($value, "\0")) {
            throw new DatabaseException('Postgres string literals cannot contain NUL bytes.');
        }

        return "'" . \str_replace("'", "''", $value) . "'";
    }

    /**
     * CREATE TABLE plus its index and comment statements.
     *
     * @return list<string>
     */
    public static function createTable(Table $table): array
    {
        $name = $table->getName();
        $clips = [];
        $primary = [];
        $after = [];
        $foreign = [];

        foreach ($table->getColumns() as $column) {
            $p = $column->getParameters();
            $columnName = \trim($column->getName(), '`');
            $clips[] = self::columnDefinition($column);

            $key = ($p['auto_increment'] ?? false) ? 'primary' : ($p['key'] ?? null);
            match ($key) {
                'primary' => $primary[] = $columnName,
                'unique', 'index', 'fulltext' => $after[] = self::createIndex($name, $key, [$columnName], self::indexName($name, [$columnName], $key)),
                'spatial' => throw new DatabaseException("Column '{$columnName}': SPATIAL indexes have no Postgres mapping in the schema DSL."),
                default => null,
            };

            if ($column->hasReference()) {
                $refColumn = $column->getReferenceColumn() ?: $columnName;
                $foreign[] = 'FOREIGN KEY (' . self::quote($columnName) . ') REFERENCES '
                    . self::quote($column->getReferenceTable()) . ' (' . self::quote($refColumn) . ')';
            }

            if ($column->getComment() !== '') {
                $after[] = 'COMMENT ON COLUMN ' . self::quote($name) . '.' . self::quote($columnName) . ' IS ' . self::literal($column->getComment());
            }
        }

        if ($primary !== []) {
            $clips[] = 'PRIMARY KEY (' . self::quoteList($primary) . ')';
        }
        \array_push($clips, ...$foreign);

        foreach ($table->getGroupIndexing() as $keyName => $columns) {
            $columns = \array_map(static fn (string $c): string => \trim($c, '`'), $columns);
            $after[] = self::createIndex($name, 'index', $columns, self::fit($name . '_' . $keyName));
        }

        return ['CREATE TABLE IF NOT EXISTS ' . self::quote($name) . ' (' . \implode(', ', $clips) . ')', ...$after];
    }

    /**
     * ALTER statements for a TableHelper's queued changes, in a safe order:
     * drop constraints/indexes/columns, rename columns, add columns, modify
     * columns, add indexes and foreign keys, comment, rename the table last.
     *
     * @return list<string>
     */
    public static function alterTable(TableHelper $helper): array
    {
        $c = $helper->getPendingChanges();
        $name = $c['table'];
        $alter = 'ALTER TABLE ' . self::quote($name) . ' ';
        $sql = [];

        foreach ($c['dropForeignKeys'] as $constraint) {
            $sql[] = $alter . 'DROP CONSTRAINT IF EXISTS ' . self::quote($constraint);
        }
        foreach ($c['dropIndexes'] as $index) {
            if ($index === 'PRIMARY') {
                $sql[] = $alter . 'DROP CONSTRAINT IF EXISTS ' . self::quote(self::fit($name . '_pkey'));
                continue;
            }
            // MySQL names a column key after the column; here column keys are
            // "<table>_<col>_idx|key|ftx". Drop whichever of them exists.
            $sql[] = 'DROP INDEX IF EXISTS ' . self::quote($index);
            foreach (['index', 'unique', 'fulltext'] as $kind) {
                $sql[] = 'DROP INDEX IF EXISTS ' . self::quote(self::indexName($name, [$index], $kind));
            }
        }
        foreach ($c['dropColumns'] as $columnName) {
            $sql[] = $alter . 'DROP COLUMN ' . self::quote($columnName);
        }
        foreach ($c['renameColumns'] as $old => $new) {
            $sql[] = $alter . 'RENAME COLUMN ' . self::quote($old) . ' TO ' . self::quote($new);
        }
        foreach ($c['addColumns'] as $data) {
            $column = $data['column'];
            $columnName = \trim($column->getName(), '`');
            $sql[] = $alter . 'ADD COLUMN ' . self::columnDefinition($column);
            $key = $column->getParameters()['key'] ?? null;
            if ($key === 'index' || $key === 'fulltext' || $key === 'unique') {
                $sql[] = self::createIndex($name, $key, [$columnName], self::indexName($name, [$columnName], $key));
            }
            if ($column->getComment() !== '') {
                $sql[] = 'COMMENT ON COLUMN ' . self::quote($name) . '.' . self::quote($columnName) . ' IS ' . self::literal($column->getComment());
            }
        }
        foreach ($c['modifyColumns'] as $data) {
            \array_push($sql, ...self::modifyColumn($alter, $data['column']));
        }
        foreach ($c['addIndexes'] as $index) {
            $sql[] = $index['type'] === 'PRIMARY'
                ? $alter . 'ADD PRIMARY KEY (' . self::quoteList($index['columns']) . ')'
                : self::createIndex($name, \strtolower($index['type']), $index['columns'], $index['name']);
        }
        foreach ($c['addForeignKeys'] as $constraint => $fk) {
            $line = $alter . 'ADD CONSTRAINT ' . self::quote($constraint) . ' FOREIGN KEY (' . self::quote($fk['column']) . ') REFERENCES '
                . self::quote($fk['refTable']) . ' (' . self::quote($fk['refColumn']) . ')';
            if ($fk['onDelete'] !== 'RESTRICT') {
                $line .= ' ON DELETE ' . $fk['onDelete'];
            }
            if ($fk['onUpdate'] !== 'RESTRICT') {
                $line .= ' ON UPDATE ' . $fk['onUpdate'];
            }
            $sql[] = $line;
        }
        if ($c['comment'] !== '') {
            $sql[] = 'COMMENT ON TABLE ' . self::quote($name) . ' IS ' . self::literal($c['comment']);
        }
        if ($c['rename'] !== '') {
            $sql[] = $alter . 'RENAME TO ' . self::quote($c['rename']);
        }

        return $sql;
    }

    /**
     * `"name" TYPE NULL|NOT NULL [DEFAULT …]`, or an identity column.
     */
    public static function columnDefinition(Column $column): string
    {
        $p = $column->getParameters();
        $name = self::quote($column->getName());

        if ($p['auto_increment'] ?? false) {
            $type = \strtoupper((string) $p['type']) === 'BIGINT' ? 'BIGINT' : 'INTEGER';

            return $name . ' ' . $type . ' GENERATED BY DEFAULT AS IDENTITY';
        }

        return $name . ' ' . self::type($p, $column->getName()) . (($p['nullable'] ?? false) ? ' NULL' : ' NOT NULL') . self::defaultClause($p, $column->getName());
    }

    /**
     * @param array<string, mixed> $p
     */
    private static function type(array $p, string $columnName): string
    {
        $type = \strtoupper((string) ($p['type'] ?? 'VARCHAR'));
        $length = (int) ($p['length'] ?? 0);
        $scale = (int) ($p['decimal_points'] ?? 0);

        return match ($type) {
            'VARCHAR', 'CHAR' => $type . '(' . ($length > 0 ? $length : 255) . ')',
            'TEXT', 'TINYTEXT', 'MEDIUMTEXT', 'LONGTEXT' => 'TEXT',
            'TINYINT' => $length === 1 ? 'BOOLEAN' : 'SMALLINT',
            'BOOL', 'BOOLEAN' => 'BOOLEAN',
            'SMALLINT', 'YEAR' => 'SMALLINT',
            'MEDIUMINT', 'INT', 'INTEGER' => 'INTEGER',
            'BIGINT' => 'BIGINT',
            'DECIMAL', 'DEC', 'NUMERIC', 'FIXED' => 'NUMERIC(' . ($length > 0 ? $length : 10) . ',' . $scale . ')',
            'FLOAT', 'REAL' => 'REAL',
            'DOUBLE', 'DOUBLE PRECISION' => 'DOUBLE PRECISION',
            'DATETIME', 'TIMESTAMP' => 'TIMESTAMP(0)',
            'DATE', 'TIME', 'UUID', 'INET', 'CIDR', 'BYTEA', 'JSONB' => $type,
            'JSON' => 'JSONB',
            'BLOB', 'TINYBLOB', 'MEDIUMBLOB', 'LONGBLOB', 'BINARY', 'VARBINARY' => 'BYTEA',
            default => throw new DatabaseException("Column '{$columnName}': type {$type} has no Postgres mapping in the schema DSL."),
        };
    }

    /**
     * @param array<string, mixed> $p
     */
    private static function defaultClause(array $p, string $columnName): string
    {
        $type = \strtoupper((string) ($p['type'] ?? ''));
        if ($p['auto_update_timestamp'] ?? false) {
            throw new DatabaseException("Column '{$columnName}': ON UPDATE CURRENT_TIMESTAMP has no Postgres equivalent; set the value in the application or a trigger.");
        }
        if ($type === 'TIMESTAMP' || $type === 'DATETIME') {
            if ($p['default_current_timestamp'] ?? false) {
                return ' DEFAULT CURRENT_TIMESTAMP';
            }

            return ($p['nullable'] ?? false) ? ' DEFAULT NULL' : '';
        }
        if (($p['nullable'] ?? false) || !\array_key_exists('default', $p) || $p['default'] === null) {
            return ($p['nullable'] ?? false) ? ' DEFAULT NULL' : '';
        }

        return ' DEFAULT ' . self::literal((string) $p['default']);
    }

    /**
     * Postgres has no MODIFY COLUMN: drop the default, change the type, set
     * nullability, then set the new default.
     *
     * @return list<string>
     */
    private static function modifyColumn(string $alter, Column $column): array
    {
        $p = $column->getParameters();
        $columnName = $column->getName();
        if ($p['auto_increment'] ?? false) {
            throw new DatabaseException("Column '{$columnName}': changing a column to auto-increment is not supported on Postgres; add a new identity column.");
        }
        $col = 'ALTER COLUMN ' . self::quote($columnName) . ' ';
        $type = self::type($p, $columnName);
        $sql = [
            $alter . $col . 'DROP DEFAULT',
            $alter . $col . 'TYPE ' . $type . ' USING CAST(' . self::quote($columnName) . ' AS ' . $type . ')',
            $alter . $col . (($p['nullable'] ?? false) ? 'DROP NOT NULL' : 'SET NOT NULL'),
        ];
        $default = \trim(self::defaultClause($p, $columnName));
        if ($default !== '' && $default !== 'DEFAULT NULL') {
            $sql[] = $alter . $col . 'SET ' . $default;
        }

        return $sql;
    }

    /**
     * @param list<string> $columns
     */
    private static function createIndex(string $table, string $kind, array $columns, string $indexName): string
    {
        $head = ($kind === 'unique' ? 'CREATE UNIQUE INDEX' : 'CREATE INDEX') . ' IF NOT EXISTS ' . self::quote($indexName) . ' ON ' . self::quote($table);

        return match ($kind) {
            'fulltext' => $head . ' USING GIN (to_tsvector(\'simple\', '
                . \implode(" || ' ' || ", \array_map(static fn (string $c): string => 'coalesce(' . self::quote($c) . ", '')", $columns)) . '))',
            'spatial' => throw new DatabaseException('SPATIAL indexes have no Postgres mapping in the schema DSL.'),
            default => $head . ' (' . self::quoteList($columns) . ')',
        };
    }

    /**
     * Index names are schema-wide in Postgres, so generated ones carry the table name.
     *
     * @param list<string> $columns
     */
    private static function indexName(string $table, array $columns, string $kind): string
    {
        $suffix = match ($kind) {
            'fulltext' => 'ftx',
            'unique' => 'key',
            default => 'idx',
        };

        return self::fit($table . '_' . \implode('_', $columns) . '_' . $suffix);
    }

    private static function fit(string $identifier): string
    {
        if (\strlen($identifier) <= self::MAX_IDENTIFIER) {
            return $identifier;
        }

        return \substr($identifier, 0, self::MAX_IDENTIFIER - 9) . '_' . \substr(\hash('sha256', $identifier), 0, 8);
    }

    /**
     * @param list<string> $columns
     */
    private static function quoteList(array $columns): string
    {
        return \implode(', ', \array_map(self::quote(...), $columns));
    }
}
